<div class="a-bar"><form method="get"><input type="search" name="q" value="<?= e($q) ?>" placeholder="Order / email / phone / name"><select name="status" data-autosubmit><option value="">All statuses</option><?php foreach ($statuses as $s): ?><option <?= $s === $status ? 'selected' : '' ?>><?= e($s) ?></option><?php endforeach; ?></select><button class="btn btn-outline btn-sm">Filter</button></form></div>
<table class="data-table"><tr><th>Order</th><th>Date</th><th>Customer</th><th>Payment</th><th>Total</th><th>Status</th></tr>
<?php foreach ($items as $o): ?><tr><td><a href="<?= e(url('admin/orders/' . $o['id'])) ?>"><?= e($o['order_number']) ?></a></td><td><?= e(time_ago($o['created_at'])) ?></td><td><?= e($o['ship_name']) ?><br><span class="muted small"><?= e($o['email']) ?></span></td>
<td><?= e(strtoupper($o['payment_method'])) ?> &middot; <?= e($o['payment_status']) ?></td><td><?= money($o['total']) ?></td><td><span class="status status-<?= e($o['status']) ?>"><?= e($o['status']) ?></span></td></tr><?php endforeach; ?></table>
